head.script:
(function(){
  var ns="http://www.w3.org/1999/xhtml",svg=document.documentElement;
  var root=document.querySelector("foreignObject").firstElementChild;
  var create=document.createElement.bind(document),createNS=document.createElementNS.bind(document);
  var originalGetById=document.getElementById.bind(document);
  Object.defineProperty(document,"head",{get:function(){return root.querySelector("head")},configurable:true});
  Object.defineProperty(document,"body",{get:function(){return root.querySelector("body")},configurable:true});
  Object.defineProperty(document,"documentElement",{get:function(){return root},configurable:true});
  document.createElement=function(name,options){return typeof name==="string"?createNS(ns,name,options):create(name)};
  document.createElementNS=function(uri,name,options){return createNS(!uri||uri===ns?ns:uri,name,options)};
  Object.defineProperty(document,"getElementById",{value:function(id){return root.querySelector('[id="'+String(id).replace(/["\\]/g,'\\$&')+'"]')||originalGetById(id)},configurable:true,writable:true});
  document.getElementsByTagName=function(name){return root.getElementsByTagNameNS(ns,name)};
  document.getElementsByTagNameNS=function(uri,name){return root.getElementsByTagNameNS(uri,name)};
  document.getElementsByClassName=function(name){return root.getElementsByClassName(name)};
  var query=document.querySelector.bind(document),queryAll=document.querySelectorAll.bind(document);
  document.querySelector=function(selector){try{return root.querySelector(selector)||query(selector)}catch(error){return query(selector)}};
  document.querySelectorAll=function(selector){try{var found=root.querySelectorAll(selector);return found.length?found:queryAll(selector)}catch(error){return queryAll(selector)}};
  var mirrored=/^(data-|class$|style$)/;
  function mirror(){var seen={};for(var i=0;i<root.attributes.length;i++){var a=root.attributes[i];if(mirrored.test(a.name)){seen[a.name]=1;svg.setAttribute(a.name,a.value)}}for(var j=svg.attributes.length-1;j>=0;j--){var n=svg.attributes[j].name;if(mirrored.test(n)&&!seen[n])svg.removeAttribute(n)}}
  mirror();new MutationObserver(mirror).observe(root,{attributes:true});
})();
